def generate(seed: int):
    rng = make_rng(FAMILY_ID, seed)
    org = rng.choice(ORGS)
    vals = dict(org=org, clients=rng.choice([300, 1200, 4000, 9000]), byok=rng.choice([5, 12, 30]), rpo=rng.choice([5, 15, 30]), log_req=rng.choice([90, 180, 365]), log_days=rng.choice([7, 14]), jit_h=rng.choice([2, 4, 8]), cell_size=rng.choice([100, 250, 500]))
    return design_review_variant(
        FAMILY_ID, seed, rng, context=org, doc_title="Целевая архитектура многоарендной платформы",
        intro="Организация — {org}: платформа обслуживает {clients} корпоративных клиентов, среди них — банки и госкомпании; архитектурный совет рассматривает целевую архитектуру безопасности.".format(**vals), lines=LINES, issues=ISSUES, vals=vals,
        length="12–20 предложений", role="главный архитектор безопасности",
        doc_kind="архитектурного документа",
        priority_crit="Расставляет приоритет по ущербу для всех арендаторов (раскрытие чужих данных, невыполнимые договоры, потеря данных, незамеченный взлом) и предлагает поэтапный план с проверкой каждого шага (тесты изоляции, учения восстановления, аудит)",
        extra_notes="Уровень Principal: важно связать пункт с требованиями из первой строки (договоры о ключах, RPO, срок журналов) и с радиусом поражения для всех арендаторов, а не перечислить меры. Числа — из условия варианта.")
